  if (pillX < margin.left) pillX = margin.left;
  var win = D.slice(Math.max(0, n - 70));
  var winMin = Math.min.apply(null, win.map(function(r){ return r[1]; }));
  var winMax5 = Math.max.apply(null, win.map(function(r){ return r[2]; }));
  var pillY = Y(winMin) + 8;
  svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
  svg.appendChild(el("text", {x: pillX + pillW / 2, y: pillY + pillH / 2 + 3, "text-anchor": "middle", "font-size": 9, "font-weight": 700, fill: "#111111", "font-family": FF}, pillText));
  svg.appendChild(el("line", {x1: lastX, x2: lastX, y1: Y(D[last][1]), y2: Y(D[last][3]), stroke: "#1f4e79", "stroke-width": 1}));
  svg.appendChild(el("text", {x: lastX - 8, y: (Y(D[last][1]) + Y(D[last][3])) / 2 + 3, "text-anchor": "end", "font-size": 8, "font-weight": 700, fill: "#1f4e79", "font-family": FF}, bp(gapNow) + " BP ABOVE POLICY RATE"));
  svg.appendChild(el("text", {x: lastX - 8, y: Y(winMax5) - 6, "text-anchor": "end", "font-size": 8, fill: "#6b84a0", "font-family": FF}, "GOC 5-YR " + D[last][2].toFixed(2) + "%"));
  svg.appendChild(el("text", {x: margin.left + 8, y: Y(D[last][3]) + 11, "text-anchor": "start", "font-size": 8, fill: "#666666", "font-family": FF}, "BOC POLICY RATE " + D[last][3].toFixed(2) + "%"));
  function labelAt(x, y, s, sz, col){
    var w = s.length * sz * 0.68;
    var nearRight = x + w > margin.left + PW;
    svg.appendChild(el("text", {x: nearRight ? x - 8 : x, y: y, "text-anchor": nearRight ? "end" : "start", "font-size": sz, fill: col, "font-family": FF}, s));
  }
  labelAt(xp(iCut) + 4, MT + 10, "OCT 30: BOC CUT TO " + D[iCut][3].toFixed(2) + "%", 7.5, "#666666");
  labelAt(xp(iFeb) + 4, MT + 10, "FEB 27: 2-YR " + D[iFeb][1].toFixed(2) + "%", 7.5, "#666666");
  labelAt(xp(iFeb) + 4, MT + 22, "2-YR UP " + bp(risePct2) + " BP SINCE, POLICY RATE UNCHANGED", 8, "#444444");
  yt.forEach(function(v){ svg.appendChild(el("text", {x: margin.left - 6, y: Y(v) + 3, "text-anchor": "end", "font-size": 8.5, fill: "#aaaaaa", "font-family": FF}, v.toFixed(2) + "%")); });
  mt.forEach(function(m){ svg.appendChild(el("text", {x: XT(m[0]), y: MT + PH + 14, "text-anchor": "middle", "font-size": 8, fill: "#999999", "font-family": FF}, mo[m[1]])); });
  svg.appendChild(el("text", {x: margin.left + PW / 2, y: MT + PH + 32, "text-anchor": "middle", "font-size": 7.5, "font-weight": 700, fill: "#bbbbbb", "font-family": FF}, "MONTH START, OCT 2025 TO OCT 2026"));
  svg.appendChild(el("text", {x: margin.left, y: MT - 6, "text-anchor": "start", "font-size": 7.5, "font-weight": 700, fill: "#bbbbbb", "font-family": FF}, "YIELD AND POLICY RATE (%)"));
  _cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source: Bank of Canada Valet API (benchmark bond yields BD.CDN.2YR.DQ.YLD and BD.CDN.5YR.DQ.YLD; target overnight rate V39079); HDQ calculations. &nbsp;|&nbsp; hdq.ca</div>
