  svg.appendChild(el("line", {x1: lastX, x2: lastX, y1: Y(D[last][1]), y2: Y(D[last][2]), stroke: "#1f4e79", "stroke-width": 1}));
  var gapText = (gapNow / 10).toFixed(1) + " PT GAP, HEADLINE VS CPI-TRIM" + (gapNow === gapMax ? ", LARGEST IN SERIES" : "");
  svg.appendChild(el("text", {x: lastX - 8, y: (Y(D[last][1]) + Y(D[last][2])) / 2 + 3, "text-anchor": "end", "font-size": 8, "font-weight": 700, fill: "#1f4e79", "font-family": FF}, gapText));
  var lgX = margin.left + 8, lgY = MT + 12;
  [["HEADLINE CPI", "#1f4e79"], ["CPI-TRIM", "#3a7a55"], ["CPI-MEDIAN", "#9fb4c8"]].forEach(function(row, k){
    svg.appendChild(el("line", {x1: lgX, x2: lgX + 14, y1: lgY + k * 11 - 3, y2: lgY + k * 11 - 3, stroke: row[1], "stroke-width": 2}));
    svg.appendChild(el("text", {x: lgX + 20, y: lgY + k * 11, "text-anchor": "start", "font-size": 8, fill: "#444444", "font-family": FF}, row[0]));
  });
  svg.appendChild(el("text", {x: xp(2) + 6, y: Y(2) - 4, "text-anchor": "start", "font-size": 7.5, fill: "#888888", "font-family": FF}, "2% TARGET MIDPOINT"));
  svg.appendChild(el("text", {x: margin.left + PW - 8, y: MT + PH - 8, "text-anchor": "end", "font-size": 7.5, fill: "#6b8f6b", "font-family": FF}, "SHADED: BELOW THE 3% TOP OF THE 1% TO 3% TARGET RANGE"));
  var nearRight = xp(iCut) + 4 + 30 * 7.5 * 0.68 > margin.left + PW;
  svg.appendChild(el("text", {x: nearRight ? xp(iCut) - 4 : xp(iCut) + 4, y: MT + PH - 20, "text-anchor": nearRight ? "end" : "start", "font-size": 7.5, fill: "#666666", "font-family": FF}, "OCT 2025: LAST POLICY RATE CHANGE"));
  yt.forEach(function(v){ svg.appendChild(el("text", {x: margin.left - 6, y: Y(v) + 3, "text-anchor": "end", "font-size": 8.5, fill: "#aaaaaa", "font-family": FF}, v.toFixed(1) + "%")); });
  D.forEach(function(r, k){ if (k % 2 === 1) svg.appendChild(el("text", {x: xp(k), y: MT + PH + 14, "text-anchor": "middle", "font-size": 7.5, fill: "#999999", "font-family": FF}, mlabel(r[0]))); });
  svg.appendChild(el("text", {x: margin.left + PW / 2, y: MT + PH + 32, "text-anchor": "middle", "font-size": 7.5, "font-weight": 700, fill: "#bbbbbb", "font-family": FF}, "YEAR OVER YEAR, MONTHLY"));
  svg.appendChild(el("text", {x: margin.left, y: MT - 6, "text-anchor": "start", "font-size": 7.5, "font-weight": 700, fill: "#bbbbbb", "font-family": FF}, "INFLATION, YEAR OVER YEAR (%)"));
  _cs.parentNode.appendChild(svg);
})();
</script>
